22:    public void ExactFinalEvidenceTag_BindsRequiredBaseCandidateTreeAndCommandReceipts()
23:    {
24:        var root = RepositoryEvidenceTestSupport.ResolveRepositoryRoot();
25:        var contractPath = Path.Combine(root, ContractRelativePath.Replace('/', Path.DirectorySeparatorChar));
26:        Assert.True(File.Exists(contractPath), $"Missing exact-final evidence contract: {contractPath}");
27:
28:        using var contract = JsonDocument.Parse(File.ReadAllText(contractPath));
29:        var contractRoot = contract.RootElement;
30:        Assert.Equal(1, contractRoot.GetProperty("schemaVersion").GetInt32());
31:        Assert.Equal(RequiredBase, contractRoot.GetProperty("requiredBaseSha").GetString());
32:        var tagName = contractRoot.GetProperty("annotatedTag").GetString();
33:        Assert.False(string.IsNullOrWhiteSpace(tagName));
34:
35:        var tagReference = "refs/tags/" + tagName;
36:        var candidateSha = RepositoryEvidenceTestSupport.RunGitText(
37:                root,
38:                ["rev-parse", tagReference + "^{commit}"])
39:            .Trim();
40:        var currentSha = RepositoryEvidenceTestSupport.RunGitText(root, ["rev-parse", "HEAD"]).Trim();
41:        Assert.Equal(currentSha, candidateSha);
42:        var candidateTree = RepositoryEvidenceTestSupport.RunGitText(
43:                root,
44:                ["rev-parse", candidateSha + "^{tree}"])
45:            .Trim();
46:        Assert.Equal(
47:            0,
48:            RepositoryEvidenceTestSupport.RunGit(root, ["merge-base", "--is-ancestor", RequiredBase, candidateSha])
49:                .ExitCode);
50:        Assert.Equal(
51:            string.Empty,
52:            RepositoryEvidenceTestSupport.RunGitText(root, ["status", "--porcelain=v1"]).Trim());
53:
54:        var annotation = RepositoryEvidenceTestSupport.RunGitText(
55:            root,
56:            ["for-each-ref", "--format=%(contents)", tagReference]);
57:        using var evidence = JsonDocument.Parse(annotation);
58:        var evidenceRoot = evidence.RootElement;
59:        Assert.Equal(1, evidenceRoot.GetProperty("schemaVersion").GetInt32());
60:        Assert.Equal(RequiredBase, evidenceRoot.GetProperty("requiredBaseSha").GetString());
61:        Assert.Equal(candidateSha, evidenceRoot.GetProperty("candidateSha").GetString());
62:        Assert.Equal(candidateTree, evidenceRoot.GetProperty("candidateTree").GetString());
63:        Assert.Equal("clean", evidenceRoot.GetProperty("worktreeStatus").GetString());
64:
65:        var commandReceipts = evidenceRoot.GetProperty("commandReceipts");
66:        Assert.True(commandReceipts.GetArrayLength() > 0);
67:        foreach (var receipt in commandReceipts.EnumerateArray())
68:        {
69:            Assert.False(string.IsNullOrWhiteSpace(receipt.GetProperty("command").GetString()));
70:            Assert.Equal(0, receipt.GetProperty("exitCode").GetInt32());
71:            Assert.Matches("^[0-9A-F]{64}$", receipt.GetProperty("outputSha256").GetString());
72:            Assert.True(receipt.GetProperty("total").GetInt32() >= 0);
73:            Assert.Equal(0, receipt.GetProperty("failed").GetInt32());
74:            Assert.Equal(0, receipt.GetProperty("skipped").GetInt32());
75:        }
76:    }
